#include <stdio.h>
#include <string.h>

#include "lwan-config.h"
#include "lwan-status.h"

static void indent(int level)
{
    for (int i = 0; i < level; i++) {
        putchar(' ');
        putchar(' ');
    }
}

static void
dump(struct config *config, struct config_line *line, int indent_level)
{
    if (indent_level > 64) {
        lwan_status_critical("Indent level %d above limit, aborting",
                             indent_level);
        return;
    }

    while (config_read_line(config, line)) {
        switch (line->type) {
        case CONFIG_LINE_TYPE_LINE:
            indent(indent_level);

            if (strchr(line->value, '\n'))
                printf("%s = '''%s'''\n", line->key, line->value);
            else
                printf("%s = %s\n", line->key, line->value);
            break;

        case CONFIG_LINE_TYPE_SECTION_END:
            if (indent_level == 0)
                lwan_status_critical("Section ended before it started");
            return;

        case CONFIG_LINE_TYPE_SECTION:
            indent(indent_level);
            printf("%s %s {\n", line->key, line->value);

            dump(config, line, indent_level + 1);

            indent(indent_level);
            printf("}\n");
            break;
        }
    }

    if (config_last_error(config)) {
        lwan_status_critical("Error while reading configuration file (line %d): %s",
                             config_cur_line(config),
                             config_last_error(config));
    }
}

int main(int argc, char *argv[])
{
    struct config *config;
    struct config_line line;
    int indent_level = 0;

    if (argc < 2) {
        lwan_status_critical("Usage: %s /path/to/config/file.conf", argv[0]);
        return 1;
    }

    config = config_open(argv[1]);
    if (!config) {
        lwan_status_critical_perror("Could not open configuration file %s",
                                    argv[1]);
        return 1;
    }

    dump(config, &line, indent_level);

    config_close(config);

    return 0;
